/* bt_prelude.js — Business Text 패널 공용 JS 프리앰블.
   각 변형 생성기가 자기 렌더 코드 앞에 이 파일을 통째로 붙인다.

   ── Business Text v6 실행 규약 (소스 실측) ─────────────────────────────
   - 이 코드는 new Function('context', code) 로 실행된다 → 변수명은 context.
   - **반환값은 렌더에 쓰이지 않는다.** 실제 렌더는 content(Handlebars) 가 한다.
     → helper 를 등록하고 content 에서 {{{이름}}} 으로 부른다.
   - renderMode='data' 일 때 context.panelData.series 에 전 refId 프레임이 들어온다.

   ── 살아남는 것 / 죽는 것 (배포된 번들에서 확인) ───────────────────────
     textUtil.sanitize = DOMPurify.sanitize(h, {USE_PROFILES:{html:true},
                                                FORBID_TAGS:["form","input"]})
     살아남음 : table/td/colspan, div, span, button, class, style(inline),
                data-*, flexbox, position:absolute, repeating-linear-gradient
     죽음     : <svg> 전체(html 프로파일에 svg 없음), <script>, on* 핸들러
   → 도형은 전부 CSS 로 그린다. SVG 를 쓰면 조용히 사라진다.

   ── CSS 작성 규칙 (지키지 않으면 패널이 통째로 투명해진다) ─────────────
   1. options.styles 에 :root{} 를 쓰지 말 것 — 문서 전역으로 새어 다른 패널을 망친다.
   2. color-mix()/var() 로 **목업 토큰**을 참조하지 말 것. --panel 같은 건 Grafana 에
      없어서 값이 unresolvable 이 되고, 그러면 그 선언 전체가 무효화된다.
      (배경과 테두리가 둘 다 color-mix 면 타일이 완전 투명해져 "빈 패널" 로 보인다)
      → 리터럴 rgba() 를 쓰거나, var() 는 반드시 폴백과 함께: var(--x, rgba(...))
   3. 인라인 커스텀 프로퍼티(style="--tc:#2a78d6")는 통과한다 — 팀 색은 이 방식으로 넘긴다. */

/* Grafana Vector/배열 양쪽 호환 */
function arr(f) {
  return (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []);
}

/* refId 프레임 → { <keyLabel 값>: {라벨..., __v: 값} }

   ⚠ 프레임 형태가 두 가지다 (실측):
     (a) time_series — 시리즈마다 프레임 1개, **라벨이 값 필드(field.labels)에** 붙는다.
         /api/ds/query 백엔드 직접 호출로 확인한 모양이 이것.
     (b) table — 라벨이 컬럼으로 펼쳐진 프레임 1개.
         format:"table" 은 Prometheus **프론트엔드** 데이터소스가 적용하므로
         패널 안에서는 이쪽이 올 수 있다.
   렌더 없이 어느 쪽인지 확정할 수 없어 **둘 다 처리**한다. */
function collectBy(series, refId, keyLabel) {
  const key = keyLabel || "queue";
  const out = {};
  series.filter(s => s.refId === refId).forEach(f => {
    const names = (f.fields || []).map(x => x.name);

    if (names.indexOf(key) >= 0) {                    /* (b) table 형태 */
      const cols = {};
      names.forEach((n, i) => { cols[n] = arr(f.fields[i]); });
      let vn = names.find(n => n === "Value" || n.indexOf("Value") === 0);
      if (!vn) vn = names.find(n => n !== "Time" && f.fields[names.indexOf(n)].type === "number");
      (cols[key] || []).forEach((k, r) => {
        const rec = out[k] || (out[k] = {});
        names.forEach(n => { if (n !== "Time") rec[n] = cols[n][r]; });
        if (vn) rec.__v = cols[vn][r];
      });
      return;
    }

    /* (a) time_series 형태 — 라벨이 값 필드에 */
    const vf = (f.fields || []).find(x => x.type === "number")
            || (f.fields || [])[(f.fields || []).length - 1];
    const lab = (vf && vf.labels) || {};
    if (lab[key] == null) return;
    const rec = out[lab[key]] || (out[lab[key]] = {});
    Object.keys(lab).forEach(k => { rec[k] = lab[k]; });
    const vs = arr(vf);
    rec.__v = vs.length ? vs[vs.length - 1] : null;
  });
  return out;
}
function collect(series, refId) { return collectBy(series, refId, "queue"); }

/* {키: 레코드} → {키: 값} */
function val(m) { const o = {}; Object.keys(m).forEach(k => { o[k] = m[k].__v; }); return o; }

/* 라벨 없는 스칼라 (cluster:shared_pool_vcores 등) */
function scalarOf(series, refId) {
  const f = series.filter(s => s.refId === refId)[0];
  if (!f) return null;
  const vf = (f.fields || []).find(x => x.type === "number")
          || (f.fields || [])[(f.fields || []).length - 1];
  const vs = arr(vf);
  return (vs && vs.length) ? vs[vs.length - 1] : null;
}

/* ── 서식 ──────────────────────────────────────────────────────────── */
const fmt = (v, d) => (v == null || isNaN(v)) ? "—"
  : Number(v).toLocaleString("ko-KR", { minimumFractionDigits: d || 0, maximumFractionDigits: d || 0 });
const pct = (a, b) => (b && a != null && !isNaN(a)) ? a / b * 100 : null;
const esc = (s) => String(s == null ? "" : s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/* ── 상태 판정 ─────────────────────────────────────────────────────────
   임계는 목업과 동일: 75 주의 / 90 임박 / 100 초과.

   ⚠ "관측 없음"과 "0%" 를 반드시 구분한다.
   현재 6개 큐 중 4개는 queue:used_* 시리즈가 **아예 없다**(0 이 아니라 부재).
   zero-fill 로 0 을 채워 넣고 그냥 그리면 "여유(초록)" 로 렌더되는데, 이건
   유휴가 아니라 미관측이다 — 관측 못 하는 큐를 건강하다고 단언하게 된다.
   그래서 값이 null 이면 별도 'none' 상태로 회색 처리한다. */
function stat(p) {
  if (p == null || isNaN(p)) return ["none", "관측 없음"];
  if (p >= 100) return ["crit", "초과"];
  if (p >= 90)  return ["ser", "임박"];
  if (p >= 75)  return ["warn", "주의"];
  return ["ok", "여유"];
}

/* ── 빈 패널 진단 ──────────────────────────────────────────────────────
   쿼리는 통과했는데 화면이 비는 경우가 이 패널의 대표 실패 모드다.
   헤드리스 브라우저를 못 띄우는 환경이라 API 검증으로는 절대 안 잡힌다.
   → 렌더할 게 없으면 프레임 구조를 화면에 출력해 원인을 눈으로 볼 수 있게 한다.
   각 변형은 데이터가 비면 반드시 bail(...) 후 return 할 것. */
function bail(H, helperName, S, why) {
  const dump = (S || []).map(s => {
    const names = (s.fields || []).map(f => f.name).join("/");
    return esc(s.refId) + "[" + names + "]";
  }).join(" · ");
  H.registerHelper(helperName, () => new H.SafeString(
    '<div style="padding:14px;line-height:1.7;font-size:12px;opacity:.8">'
    + '<b>데이터 없음</b> — ' + esc(why) + '<br>'
    + 'frames=' + (S || []).length + '<br>'
    + (dump || '(프레임 없음)')
    + '</div>'));
}

/* 공용 팔레트 — 목업 _SPEC.md 와 동일 */
const COLORS = {
  "AI/Data Platform": "#2a78d6", "품질 지능화": "#eb6834",
  "EES/MDM/IPA": "#1baf7a", "장비 지능화": "#eda100"
};
const ORDER = ["root.platform", "root.fdc", "root.smartbig", "root.yms", "root.tttm", "root.pluto"];
const TEAM_ORDER = ["AI/Data Platform", "품질 지능화", "EES/MDM/IPA", "장비 지능화"];

const H = context.handlebars;
const S = (context.panelData && context.panelData.series) || [];

const tq = val(collectBy(S,"tq","team")), tu = val(collectBy(S,"tu","team"));
const teams = TEAM_ORDER.filter(x => tq[x] != null);
if (!teams.length) { bail(H,'bullets',S,'team:quota_vcores 가 비었습니다.'); return; }

/* 축 최대 = 최대 보장 × 1.25 → 100% 기준선이 항상 같은 자리에 온다 */
const axis = Math.max.apply(null, teams.map(x => tq[x]||0)) * 1.25;

let h = '<div class="hd">팀별 보장자원 대비 사용'
      + '<em>막대 = 사용량 · 세로선 = 보장선 · 빗금 = 공용자원에서 끌어쓴 몫</em></div>';
h += '<div class="lg2"><span><i class="sw fs"></i>보장 범위 내</span>'
   + '<span><i class="sw os"></i>공용자원 사용분</span>'
   + '<span><i class="sw ms"></i>보장선(guaranteed)</span></div>';
h += '<table class="tb">';
teams.forEach(x => {
  const q = tq[x], u = tu[x];
  const known = u != null;
  const inb = known ? Math.min(u,q)/axis*100 : 0;
  const ovr = known ? Math.max(0,u-q)/axis*100 : 0;
  h += '<tr><td class="l nmcell"><span class="dot" style="background:' + COLORS[x] + '"></span>'
     + esc(x) + '</td>'
     + '<td class="barcell"><div class="trk" style="--tc:' + COLORS[x] + '">'
     + (known ? '<i class="base" style="width:' + inb.toFixed(2) + '%"></i>' : '')
     + (ovr > 0 ? '<i class="ovr" style="left:' + inb.toFixed(2) + '%;width:' + ovr.toFixed(2) + '%"></i>' : '')
     + '<u style="left:' + (q/axis*100).toFixed(2) + '%"></u></div></td>'
     + '<td class="vcell">' + (known ? '<b>'+fmt(u,2)+'</b>' : '<span class="nd">관측 없음</span>')
     + ' <span class="sl">/ ' + fmt(q,2) + '</span></td></tr>';
});
h += '</table>';
H.registerHelper('bullets', () => new H.SafeString(h));

